import type { CartItem } from "./data";
import CartItemRow from "./CartItemRow";
import Summary from "./Summary";

type Props = { cart: CartItem[]; onChangeQty: (id: number, delta: number) => void; onClear: () => void };

export default function CartView({ cart, onChangeQty, onClear }: Props) {
  if (cart.length === 0) return <span className="text-gray-500">El carrito está vacío</span>;
  return (
    <div className="flex flex-col gap-2">
      {cart.map((item) => (
        <CartItemRow key={item.product.id} item={item} onChangeQty={(d) => onChangeQty(item.product.id, d)} />
      ))}
      <Summary cart={cart} onClear={onClear} />
    </div>
  );
}

files.Catalog.tsx:
import { useState } from "react";
import type { Product } from "./data";
import SearchBox from "./SearchBox";
import ProductCard from "./ProductCard";

export default function Catalog({ products, onAdd }: { products: Product[]; onAdd: (p: Product) => void }) {
  const [query, setQuery] = useState("");
  const [sortByPrice, setSortByPrice] = useState(false);
  const filtered = products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()));
  const shown = sortByPrice ? [...filtered].sort((a, b) => a.price - b.price) : filtered;

  return (
    <div className="flex flex-col gap-2">
      <SearchBox value={query} onChange={setQuery} />
      <button
        type="button"
        onClick={() => setSortByPrice((s) => !s)}
        aria-pressed={sortByPrice}
        className={`self-start rounded border px-3 py-1 text-sm ${
          sortByPrice ? "bg-blue-600 text-white border-blue-600" : "bg-white text-gray-800 border-gray-300"
        }`}
      >
        Ordenar por precio
      </button>
      <div className="grid grid-cols-3 gap-2">
        {shown.map((p) => (
          <ProductCard key={p.id} product={p} onAdd={() => onAdd(p)} />
        ))}
      </div>
      {shown.length === 0 && <span className="text-gray-500">Sin resultados</span>}
    </div>
  );
}

